/* ===== x04_scope.js ===== */
/* ============================================================================
   v5.5 LAYER 4 — Scope, estimates and margin: scope lines with stable ids,
   estimate-to-complete per line, procurement completion & reserve release,
   explained margin variance (bridge), per-function allocation, scenarios,
   immutable quote snapshots with comparison, inclusions/exclusions/assumptions,
   unit-aware price book, profitability by segment.
   ========================================================================== */
coll('scopeLines','scenarios','priceBook');
window.ON_ACCEPT=window.ON_ACCEPT||[];window.ON_SEND=window.ON_SEND||[];
const UNITS=['each','per guest','per plate','per day','per hour','per car','per room','lump sum'];
const scopeOf=eid=>live(S.scopeLines).filter(l=>l.eventId===eid);
function makeScopeLines(e){if(scopeOf(e.id).length)return;(e.quote.lines||[]).filter(l=>l.category!=='Crew'&&l.category!=='Expenses').forEach(l=>{S.scopeLines.push(stamp({id:'sl_'+uid(),eventId:e.id,quoteLineId:l.id,category:l.category,desc:l.desc,functionName:l.functionName||'',qty:l.qty,unit:l.perGuest?'per guest':l.qty>1?'each':'lump sum',unitCostPaise:l.unitCostPaise,unitPricePaise:l.unitPricePaise,baselineCostPaise:l.qty*l.unitCostPaise,baselinePricePaise:l.qty*l.unitPricePaise,etcPaise:null,etcBy:null,etcAt:null,etcNote:'',status:'open',releasedPaise:0,releaseReason:'',ownerId:e.plannerId,revisions:[]}))})}
ON_ACCEPT.push((e,q)=>{makeScopeLines(e);snapshotQuote(e,'Accepted by client')});
ON_SEND.push(e=>snapshotQuote(e,'Sent to client'));
/* allocation: which scope lines does a commitment cover, and for how much */
function allocOf(cm){if(cm.allocation&&cm.allocation.length){const total=cm.agreedPaise+linkedChangeCost(cm.id);const s=sum(cm.allocation,a=>a.amountPaise);if(s===total)return cm.allocation;const out=cm.allocation.map(a=>Object.assign({},a));out[out.length-1].amountPaise+=total-s;return out}if(cm.scopeLineIds&&cm.scopeLineIds.length){const per=Math.floor((cm.agreedPaise+linkedChangeCost(cm.id))/cm.scopeLineIds.length);return cm.scopeLineIds.map((id,i)=>({scopeLineId:id,amountPaise:i===cm.scopeLineIds.length-1?cm.agreedPaise+linkedChangeCost(cm.id)-per*(cm.scopeLineIds.length-1):per}))}return []}
function lineCommitted(l){return sum(costComms(l.eventId),cm=>sum(allocOf(cm).filter(a=>a.scopeLineId===l.id),a=>a.amountPaise))}
function lineEtc(l){const com=lineCommitted(l);if(l.status==='complete'||l.status==='released')return 0;if(l.etcPaise!=null)return l.etcPaise;return Math.max(0,l.baselineCostPaise-com)}
function lineForecast(l){return lineCommitted(l)+lineEtc(l)}
function scopeSummary(e){const ls=scopeOf(e.id);const cs=costComms(e.id);const unalloc=cs.filter(cm=>!allocOf(cm).length);const unallocCost=sum(unalloc,cm=>cm.agreedPaise+linkedChangeCost(cm.id));const lines=ls.map(l=>({l,committed:lineCommitted(l),etc:lineEtc(l),forecast:lineForecast(l),variance:lineForecast(l)-l.baselineCostPaise,stale:l.etcAt&&daysUntil(l.etcAt.slice(0,10))<=-30&&l.status==='open'}));return {lines,unalloc,unallocCost,forecastVendors:sum(lines,x=>x.forecast)+unallocCost,baseline:sum(ls,l=>l.baselineCostPaise),released:sum(ls,l=>l.releasedPaise||0)}}
/* Forecast v2: line-level when scope lines exist; the category floor stays as fallback for events without them */
const _calcBase=calc;calc=function(e){const c=_calcBase(e);if(!S.scopeLines||!scopeOf(e.id).length||c.cancelled)return c;const sc=scopeSummary(e);const base=e.budget&&Object.keys(e.budget).length?e.budget:(e.budgetBaseline||{});const fcCrew=Math.max(c.crew,base.Crew||0);const fcExp=Math.max(c.expenses,base.Expenses||0);
  // lines never carry crew/expense categories; vendor commitments in those categories are rare but counted via unalloc
  const forecastCost=sc.forecastVendors+c.changeCost+fcCrew+fcExp;c.forecastCost=forecastCost;c.uncommitted=forecastCost-c.costs;c.forecast=c.costplus?feeOf(e,forecastCost):c.contract-forecastCost;c.scope=sc;c.forecastBasis='scope';return c};
function snapshotQuote(e,note){const q=quoteTotals(e);e.quote.snapshots=e.quote.snapshots||[];const n=e.quote.snapshots.length+1;e.quote.snapshots.push({n,ts:nowISO(),by:UI.userId,note:note||'',lines:JSON.parse(JSON.stringify(q.lines)),discountPaise:q.discount,terms:e.quote.terms||'',validUntil:e.quote.validUntil||null,inclusions:e.quote.inclusions||'',exclusions:e.quote.exclusions||'',allowances:e.quote.allowances||'',dependencies:e.quote.dependencies||'',tax:taxTermsOf(e),pricing:e.pricing,feePct:e.feePct||0,totals:{cost:q.cost,net:q.net,gst:q.gst,gross:q.gross,margin:q.margin},attachments:live(S.docs).filter(d=>d.eventId===e.id&&d.kind==='Design').map(d=>d.id)});audit('create','quoteSnapshot',e.id+'#'+n,note,e.id)}
act('quote-snapshot',({E})=>{const e=E();openModal(`${hd('Save a quote version')}<form id="f-qs"><label for="qsn">What changed?</label><input id="qsn" required placeholder="Dropped the sangeet; 50 fewer guests">${ft('Save version')}</form>`);F('f-qs').addEventListener('submit',x=>{x.preventDefault();snapshotQuote(e,F('qsn').value.trim());save();closeModal();render();toast('Version saved')})});
act('quote-terms',({E})=>{const e=E();const q=e.quote;openModal(`${hd('Inclusions, exclusions, assumptions')}<form id="f-qt"><label for="qti">Included</label><textarea id="qti" placeholder="Mandap, stage, 400 chairs, entrance arch, 2 days setup">${esc(q.inclusions||'')}</textarea><label for="qtx">Excluded</label><textarea id="qtx" placeholder="Generator fuel, venue electricity, overtime after 11 pm">${esc(q.exclusions||'')}</textarea><label for="qta">Allowances (provisional sums)</label><textarea id="qta" placeholder="Florals allowance ₹60,000 — actual billed at cost">${esc(q.allowances||'')}</textarea><label for="qtd">Client dependencies</label><textarea id="qtd" placeholder="Final guest count by 20 Jan; venue electricity; family photographer coordination">${esc(q.dependencies||'')}</textarea><div class="two"><div><label for="qtv">Valid until</label><input id="qtv" type="date" value="${q.validUntil||''}"></div><div><label for="qtt">Payment terms text</label><input id="qtt" value="${esc(q.terms||'')}"></div></div><div class="help">These travel with every version, appear on the printable quote and the client link, and are copied onto vendor orders and change orders so nobody argues later about what was in.</div>${ft('Save')}</form>`);F('f-qt').addEventListener('submit',x=>{x.preventDefault();q.inclusions=F('qti').value.trim();q.exclusions=F('qtx').value.trim();q.allowances=F('qta').value.trim();q.dependencies=F('qtd').value.trim();q.validUntil=F('qtv').value||null;q.terms=F('qtt').value.trim();touch(e);audit('update','events',e.id,'quote terms',e.id);save();closeModal();render()})});
/* Quote tab additions: versions, comparison, terms, price-book hints */
const _tabQuoteBase=tabQuote;tabQuote=function(e,c){let h=_tabQuoteBase(e,c);const snaps=e.quote.snapshots||[];const q=e.quote;const cmp=S.ui.qcmp||{};const a=snaps.find(s=>s.n===+cmp.a),b=snaps.find(s=>s.n===+cmp.b);const lk=locked(e);
  const hints=(()=>{if(stageIdx(e.stage)>=2||!can('quote'))return '';const cats=[...new Set((q.lines||[]).map(l=>l.category))];const rows=cats.map(cat=>{const pb=priceBookFor(cat,e);return pb?`<div class="small"><b>${esc(cat)}</b>: ${pb.text}</div>`:''}).filter(Boolean);return rows.length?`<div class="card" style="margin-top:12px"><h3>Price book says</h3><div class="small muted">From your own closed events and entries, with sample size and date. Not a quote — a sanity check.</div><div style="margin-top:6px">${rows.join('')}</div></div>`:''})();
  const terms=`<div class="card" style="margin-top:12px"><div class="row between"><h3>What is in, what is out</h3>${lk?'':`<button class="btn sm" data-act="quote-terms">Edit</button>`}</div>${q.inclusions||q.exclusions||q.allowances||q.dependencies?`<div class="kv" style="margin-top:6px"><b>Included</b><span>${esc(q.inclusions||'—')}</span><b>Excluded</b><span>${esc(q.exclusions||'—')}</span><b>Allowances</b><span>${esc(q.allowances||'—')}</span><b>Client must provide</b><span>${esc(q.dependencies||'—')}</span><b>Valid until</b><span>${q.validUntil?fmtDate(q.validUntil)+(q.validUntil<todayStr()&&stageIdx(e.stage)<2?' <span class="pill bad">expired</span>':''):'—'}</span></div>`:'<div class="muted small" style="margin-top:4px">Nothing recorded. Every dispute at close-out starts here — fill it in before sending.</div>'}</div>`;
  const vers=`<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Versions (${snaps.length})</h3><div class="small muted">Complete immutable copies: every line, the terms, tax and totals at that moment. Sending and acceptance save one automatically.</div></div>${lk||!can('quote')?'':`<button class="btn sm" data-act="quote-snapshot">Save version now</button>`}</div>${snaps.length?`<div class="list" style="margin-top:6px">${snaps.slice().reverse().map(s=>`<div class="item" style="padding:6px 0"><b>v${s.n}</b> · ${fmtTs(s.ts)} · ${esc(user(s.by).name)} · ${esc(s.note)}<div class="meta">${s.lines.length} lines · price ${inr(s.totals.net)} · cost ${inr(s.totals.cost)} · margin ${pct(s.totals.margin,s.totals.net)} · ${s.tax.on?'GST '+s.tax.pct+'%':'no GST'}${s.validUntil?' · valid to '+fmtDate(s.validUntil):''}</div></div>`).join('')}</div>${snaps.length>1?`<div class="row" style="gap:6px;margin-top:8px"><span class="small">Compare</span><select data-act="qcmp-a" style="width:auto;padding:6px 10px;font-size:13px">${snaps.map(s=>`<option value="${s.n}" ${+cmp.a===s.n?'selected':''}>v${s.n}</option>`).join('')}</select><span class="small">with</span><select data-act="qcmp-b" style="width:auto;padding:6px 10px;font-size:13px">${snaps.map(s=>`<option value="${s.n}" ${+cmp.b===s.n?'selected':''}>v${s.n}</option>`).join('')}</select></div>${a&&b&&a!==b?snapDiff(a,b):''}`:''}`:''}</div>`;
  return h+hints+terms+vers};
ACTS_CHANGE['qcmp-a']=el=>{S.ui.qcmp=Object.assign(S.ui.qcmp||{},{a:el.value});saveUI();render()};ACTS_CHANGE['qcmp-b']=el=>{S.ui.qcmp=Object.assign(S.ui.qcmp||{},{b:el.value});saveUI();render()};
function snapDiff(a,b){const key=l=>l.id||(l.category+'|'+l.desc);const am=new Map(a.lines.map(l=>[key(l),l])),bm=new Map(b.lines.map(l=>[key(l),l]));const rows=[];for(const [k,l] of bm){const o=am.get(k);if(!o)rows.push(`<tr><td><span class="pill ok">added</span> ${esc(l.category)} · ${esc(l.desc)}</td><td class="r num">—</td><td class="r num">${inr(l.qty*l.unitPricePaise)}</td></tr>`);else if(o.qty!==l.qty||o.unitCostPaise!==l.unitCostPaise||o.unitPricePaise!==l.unitPricePaise)rows.push(`<tr><td><span class="pill warn">changed</span> ${esc(l.category)} · ${esc(l.desc)}<div class="meta">${o.qty}×${inr(o.unitPricePaise)} → ${l.qty}×${inr(l.unitPricePaise)}; cost ${inr(o.unitCostPaise)} → ${inr(l.unitCostPaise)}</div></td><td class="r num">${inr(o.qty*o.unitPricePaise)}</td><td class="r num">${inr(l.qty*l.unitPricePaise)}</td></tr>`)}for(const [k,o] of am)if(!bm.has(k))rows.push(`<tr><td><span class="pill bad">removed</span> ${esc(o.category)} · ${esc(o.desc)}</td><td class="r num">${inr(o.qty*o.unitPricePaise)}</td><td class="r num">—</td></tr>`);const t=[['Price',a.totals.net,b.totals.net],['Cost',a.totals.cost,b.totals.cost],['Margin',a.totals.margin,b.totals.margin]];return `<div class="scroll" style="margin-top:8px"><table><thead><tr><th>Line</th><th class="r">v${a.n}</th><th class="r">v${b.n}</th></tr></thead><tbody>${rows.join('')||'<tr><td colspan="3" class="muted">No line differences.</td></tr>'}${t.map(([n,x,y])=>`<tr><td><b>${n}</b></td><td class="r num">${inr(x)}</td><td class="r num"><b>${inr(y)}</b> <span class="small muted">${y-x>=0?'+':'−'}${inr(Math.abs(y-x))}</span></td></tr>`).join('')}${a.exclusions!==b.exclusions||a.inclusions!==b.inclusions?`<tr><td colspan="3" class="small">Terms changed: <i>${esc(a.exclusions||'—')}</i> → <i>${esc(b.exclusions||'—')}</i></td></tr>`:''}</tbody></table></div>`}
/* ---------- Scope tab ---------- */
addTab('scope','Scope & forecast',tabScope,(e,pre)=>!pre&&can('budget.view'),'Money');
function tabScope(e,c){const sc=scopeSummary(e);const money=seesMoney();const profit=can('profit');const lk=locked(e);const edit=can('budget')&&!lk;const fns=fnNames(e);
  if(!sc.lines.length)return `<div class="card"><h2>Scope lines</h2><div class="small muted">This event was confirmed before scope lines existed. Create them from the accepted quote; every vendor commitment can then be linked to the line it buys.</div>${edit?`<button class="btn pri" style="margin-top:8px" data-act="scope-make">Create scope lines from the quote</button>`:''}</div>`;
  const rows=sc.lines.map(x=>{const l=x.l;const st=l.status==='complete'?'<span class="pill ok">fully bought</span>':l.status==='released'?'<span class="pill grey">reserve released</span>':x.committed>=l.baselineCostPaise?'<span class="pill warn">at/over baseline, still open</span>':x.committed>0?'<span class="pill grey">partly bought</span>':'<span class="pill bad">nothing booked</span>';const cms=costComms(e.id).filter(cm=>allocOf(cm).some(a=>a.scopeLineId===l.id));
    return `<tr class="${l.status!=='open'?'done':''}"><td><b>${esc(l.category)}</b> · ${esc(l.desc)}<div class="meta">${l.qty} ${esc(l.unit)}${l.functionName?' · '+esc(l.functionName):''} · owner ${esc(user(l.ownerId).name)}${cms.length?' · '+cms.map(cm=>esc(vendor(cm.vendorId).name)).join(', '):''}</div><div style="margin-top:3px">${st}${x.stale?' <span class="pill warn">estimate 30+ days old</span>':''}</div></td>${money?`<td class="r num">${inr(l.baselineCostPaise)}</td><td class="r num">${inr(x.committed)}</td><td class="r num">${x.etc?inr(x.etc):'—'}${l.etcPaise!=null&&l.status==='open'?`<div class="meta">by ${esc(user(l.etcBy).name)} ${fmtShort(l.etcAt.slice(0,10))}</div>`:l.status==='open'&&x.etc?'<div class="meta">baseline remainder</div>':''}</td><td class="r num"><b>${inr(x.forecast)}</b></td><td class="r num" style="color:${x.variance>0?'var(--bad)':x.variance<0?'var(--ok)':'inherit'}">${x.variance?(x.variance>0?'+':'−')+inr(Math.abs(x.variance)):'—'}</td>`:''}<td>${edit?`<div class="row" style="gap:4px"><button class="btn sm" data-act="scope-etc" data-id="${l.id}">Estimate</button>${l.status==='open'?`<button class="btn sm" data-act="scope-complete" data-id="${l.id}">Fully bought</button>`:`<button class="btn sm" data-act="scope-reopen" data-id="${l.id}">Reopen</button>`}<button class="btn sm" data-act="scope-edit" data-id="${l.id}">Edit</button></div>`:''}</td></tr>`}).join('');
  const bridge=profit?marginBridge(e,c):null;
  return `<div class="card"><div class="row between"><div><h2>Scope & forecast</h2><div class="small muted">One row per vendor-delivered thing you sold (crew and sundries are forecast from assignments and expenses, not here). <b>Bought</b> is what vendors have agreed for it; <b>Still to buy</b> is your estimate for the rest (baseline remainder until someone enters a better number); <b>Forecast</b> is the sum. Marking a line <b>fully bought</b> releases its unused reserve — that is how a cheaper vendor turns into margin instead of sitting as a silent cushion.</div></div>${edit?`<div class="row" style="gap:6px"><button class="btn sm" data-act="scope-add">+ Line</button><button class="btn sm" data-act="scenario-new">What-if</button></div>`:''}</div>
  <div class="scroll" style="margin-top:8px"><table><thead><tr><th>Scope line</th>${money?'<th class="r">Baseline</th><th class="r">Bought</th><th class="r">Still to buy</th><th class="r">Forecast</th><th class="r">vs baseline</th>':''}<th></th></tr></thead><tbody>${rows}${money?`<tr><td><b>Total scope</b></td><td class="r num"><b>${inr(sc.baseline)}</b></td><td class="r num"><b>${inr(sum(sc.lines,x=>x.committed))}</b></td><td class="r num"><b>${inr(sum(sc.lines,x=>x.etc))}</b></td><td class="r num"><b>${inr(sum(sc.lines,x=>x.forecast))}</b></td><td class="r num"><b>${sum(sc.lines,x=>x.variance)>=0?'+':'−'}${inr(Math.abs(sum(sc.lines,x=>x.variance)))}</b></td><td></td></tr>`:''}</tbody></table></div>
  ${sc.unalloc.length&&money?`<div class="note" style="margin-top:8px"><b>${sc.unalloc.length} vendor agreement(s) not linked to a scope line</b> (${inr(sc.unallocCost)}): ${sc.unalloc.map(cm=>`${esc(vendor(cm.vendorId).name)} ${inr(cm.agreedPaise)} <button class="btn sm" data-act="scope-link" data-id="${cm.id}">Link</button>`).join(' · ')}. Unlinked cost is in the forecast as its own line but cannot release any reserve.</div>`:''}
  ${profit?`<div class="grid g3" style="margin-top:10px">${stat('Forecast cost',inr(c.forecastCost),`scope ${inr(sc.forecastVendors)} + changes ${inr(c.changeCost)} + crew/expenses ${inr(c.forecastCost-sc.forecastVendors-c.changeCost)}`)}${stat('Forecast margin',inr(c.forecast),pct(c.forecast,c.contract),true)}${stat('Reserve released',inr(sc.released),'from lines marked fully bought')}</div>`:''}
  ${bridge?`<div class="card" style="margin-top:12px"><h3>Why the margin moved</h3><div class="small muted">From the margin you priced in to the margin you now expect, step by step. Each step points at the records behind it.</div><div class="scroll" style="margin-top:6px"><table><tbody>${bridge.map(b=>`<tr><td>${esc(b.label)}<div class="meta">${esc(b.why)}</div></td><td class="r num" style="color:${b.amt>0?'var(--ok)':b.amt<0?'var(--bad)':'inherit'}">${b.total!=null?`<b>${inr(b.total)}</b>`:(b.amt>=0?'+':'−')+inr(Math.abs(b.amt))}</td></tr>`).join('')}</tbody></table></div></div>`:''}
  ${money&&fns.length>1?fnAllocation(e,c):''}
  ${scenariosCard(e)}</div>`}
function marginBridge(e,c){const q=quoteTotals(e);const sc=scopeSummary(e);const steps=[];const quoted=q.net?q.margin:0;steps.push({label:'Margin priced in the accepted quote',why:`price ${inr(q.net)} − cost ${inr(q.cost)}`,total:quoted,amt:0});
  const qtyRate=sum(sc.lines,x=>{const ql=(e.quote.lines||[]).find(l=>l.id===x.l.quoteLineId);if(!ql)return 0;return (ql.qty*ql.unitCostPaise)-x.l.baselineCostPaise});if(qtyRate)steps.push({label:'Quantity / rate changes on scope lines',why:'scope line baselines edited after acceptance',amt:qtyRate});
  const over=sum(sc.lines.filter(x=>x.l.status!=='open'),x=>x.l.baselineCostPaise-x.committed);if(over)steps.push({label:over>0?'Bought cheaper than baseline (reserve released)':'Bought dearer than baseline (overrun)',why:sc.lines.filter(x=>x.l.status!=='open'&&x.l.baselineCostPaise!==x.committed).map(x=>`${x.l.category} ${x.committed>x.l.baselineCostPaise?'+':'−'}${inr(Math.abs(x.committed-x.l.baselineCostPaise))}`).join(', '),amt:over});
  const openVar=sum(sc.lines.filter(x=>x.l.status==='open'),x=>x.l.baselineCostPaise-x.forecast);if(openVar)steps.push({label:'Open lines: committed + estimate vs baseline',why:'lines still being bought; estimate-to-complete entered or baseline remainder',amt:openVar});
  const chs=live(S.changes).filter(x=>x.eventId===e.id&&chApproved(x));const chNet=sum(chs,x=>x.clientPaise-((x.commitmentId||x.generatedCommitmentId)?0:x.costPaise));if(chs.length)steps.push({label:`Approved changes (${chs.length})`,why:chs.map(x=>`${x.desc}: +${inr(x.clientPaise)} / cost ${inr(x.costPaise)}${(x.commitmentId||x.generatedCommitmentId)?' (cost already inside its vendor line above)':''}`).join('; '),amt:chNet});
  const cm=c.contract-c.forecastCost;const base=e.budget&&Object.keys(e.budget).length?e.budget:(e.budgetBaseline||{});const crewExp=((base.Crew||0)+(base.Expenses||0))-(Math.max(c.crew,base.Crew||0)+Math.max(c.expenses,base.Expenses||0));if(crewExp)steps.push({label:'Crew and expenses over their baseline',why:`crew ${inr(c.crew)}, expenses ${inr(c.expenses)}`,amt:crewExp});
  const unl=-sc.unallocCost;if(unl)steps.push({label:'Vendor agreements not linked to any line',why:'cost added on top because no line could absorb it',amt:unl});
  const explained=quoted+sum(steps.filter(s=>s.total==null),s=>s.amt);const resid=(c.costplus?c.forecast:cm)-explained;if(Math.abs(resid)>=100)steps.push({label:'Other (discount, rounding, cost-plus fee basis)',why:'difference not attributable to a single record',amt:resid});
  steps.push({label:'Forecast margin now',why:`contract ${inr(c.contract)} − forecast cost ${inr(c.forecastCost)}`,total:c.forecast,amt:0});return steps}
function fnAllocation(e,c){const fns=fnNames(e);const rev={},cost={};fns.forEach(f=>{rev[f]=0;cost[f]=0});const shared={rev:0,cost:0};scopeOf(e.id).forEach(l=>{if(l.functionName&&rev[l.functionName]!==undefined)rev[l.functionName]+=l.baselinePricePaise;else shared.rev+=l.baselinePricePaise});costComms(e.id).forEach(cm=>{const amt=cm.agreedPaise+linkedChangeCost(cm.id);const f=(cm.functions||[]).filter(x=>fns.includes(x));if(f.length){f.forEach(x=>cost[x]+=Math.round(amt/f.length))}else shared.cost+=amt});live(S.expenses).filter(x=>x.eventId===e.id&&!(x.status==='declined'&&x.source==='own')).forEach(x=>{if(x.functionName&&cost[x.functionName]!==undefined)cost[x.functionName]+=x.amountPaise;else shared.cost+=x.amountPaise});const guests=sum(fns,f=>fnOf(e,f).guests||0)||1;return `<div class="card" style="margin-top:12px"><h3>By function</h3><div class="small muted">Revenue from scope lines tagged to a function; vendor cost split equally across the functions an agreement covers; expenses by their function. Shared items (untagged) are spread by headcount. Rule shown so nobody mistakes it for truth.</div><div class="scroll" style="margin-top:6px"><table><thead><tr><th>Function</th><th class="r">Guests</th><th class="r">Revenue</th><th class="r">Cost</th><th class="r">Margin</th></tr></thead><tbody>${fns.map(f=>{const g=fnOf(e,f).guests||0;const r=rev[f]+Math.round(shared.rev*g/guests),k=cost[f]+Math.round(shared.cost*g/guests);return `<tr><td><b>${esc(f)}</b></td><td class="r num">${g}</td><td class="r num">${inr(r)}</td><td class="r num">${inr(k)}</td><td class="r num" style="color:${r-k<0?'var(--bad)':'inherit'}">${inr(r-k)} <span class="small muted">${pct(r-k,r)}</span></td></tr>`}).join('')}<tr><td class="small muted">of which shared, spread by headcount</td><td></td><td class="r num small muted">${inr(shared.rev)}</td><td class="r num small muted">${inr(shared.cost)}</td><td></td></tr></tbody></table></div></div>`}
act('scope-make',({E})=>{const e=E();makeScopeLines(e);audit('create','scopeLines',e.id,'from quote',e.id);save();render()});
act('scope-etc',({id})=>{const l=S.scopeLines.find(x=>x.id===id);const com=lineCommitted(l);openModal(`${hd('Still to buy: '+esc(l.category))}<form id="f-etc"><p class="small">${esc(l.desc)} · baseline ${inr(l.baselineCostPaise)} · bought ${inr(com)} · current estimate ${inr(lineEtc(l))}${l.etcPaise==null?' (baseline remainder)':''}</p><label for="etca">Your estimate of what is still to be spent on this line (₹)</label><input id="etca" class="big" inputmode="decimal" value="${l.etcPaise!=null?l.etcPaise/100:Math.max(0,l.baselineCostPaise-com)/100}"><label for="etcn">Why (quote in hand, market rate, nothing left…)</label><input id="etcn" value="${esc(l.etcNote||'')}" placeholder="Bloom & Co quoted ₹32k for florals"><div class="help">Dated and owned: a 30-day-old estimate is flagged. Enter 0 only if truly nothing more will be spent — or use Fully bought, which also releases the reserve.</div><div class="ft"><button class="btn" data-act="close">Cancel</button><button class="btn" type="button" data-act="scope-etc-clear" data-id="${l.id}">Back to baseline remainder</button><button class="btn pri" type="submit">Save estimate</button></div></form>`);F('f-etc').addEventListener('submit',x=>{x.preventDefault();const a=toPaise(F('etca').value);if(a==null||a<0)return toast('Enter an amount');l.revisions.push({ts:nowISO(),by:UI.userId,f:'etc',from:l.etcPaise,to:a});l.etcPaise=a;l.etcBy=UI.userId;l.etcAt=nowISO();l.etcNote=F('etcn').value.trim();touch(l);audit('update','scopeLines',l.id,'estimate '+inr(a),l.eventId);save();closeModal();render()})});
act('scope-etc-clear',({id})=>{const l=S.scopeLines.find(x=>x.id===id);l.etcPaise=null;l.etcBy=null;l.etcAt=null;touch(l);save();closeModal();render()});
act('scope-complete',({id})=>{const l=S.scopeLines.find(x=>x.id===id);const com=lineCommitted(l);const rel=Math.max(0,l.baselineCostPaise-com);openModal(`${hd('Fully bought')}<form id="f-sc"><p class="small">${esc(l.category)} · ${esc(l.desc)}<br>Baseline ${inr(l.baselineCostPaise)} · bought ${inr(com)} → ${rel?`<b>${inr(rel)} of reserve is released</b> into the forecast margin`:com>l.baselineCostPaise?`<b style="color:var(--bad)">overrun of ${inr(com-l.baselineCostPaise)}</b> stays in the forecast`:'exactly on baseline'}.</p>${!com?'<div class="alert">Nothing is bought on this line. Marking it complete says the scope will not be delivered by a vendor at all — only do that if it was dropped from the contract (use a change order) or is delivered by crew.</div>':''}<label for="scr">Reason</label><input id="scr" required placeholder="XYZ agreed full décor scope at ₹8.5L; nothing else to buy">${ft('Mark fully bought')}</form>`);F('f-sc').addEventListener('submit',x=>{x.preventDefault();l.status='complete';l.releasedPaise=rel;l.releaseReason=F('scr').value.trim();l.completedBy=UI.userId;l.completedAt=nowISO();l.revisions.push({ts:nowISO(),by:UI.userId,f:'status',from:'open',to:'complete',released:rel});touch(l);audit('update','scopeLines',l.id,'fully bought · released '+inr(rel)+': '+l.releaseReason,l.eventId);save();closeModal();render()})});
act('scope-reopen',({id})=>{const l=S.scopeLines.find(x=>x.id===id);l.status='open';l.revisions.push({ts:nowISO(),by:UI.userId,f:'status',from:'complete',to:'open',released:-l.releasedPaise});l.releasedPaise=0;touch(l);audit('update','scopeLines',l.id,'reopened',l.eventId);save();render()});
act('scope-edit',({id,E})=>mScopeLine(E(),S.scopeLines.find(x=>x.id===id)));act('scope-add',({E})=>mScopeLine(E(),null));
function mScopeLine(e,l){const isNew=!l;l=l||{category:'',desc:'',functionName:'',qty:1,unit:'each',unitCostPaise:0,unitPricePaise:0,ownerId:e.plannerId};openModal(`${hd(isNew?'Add scope line':'Edit scope line')}<form id="f-sl"><div class="two"><div><label for="slc">Category</label><select id="slc">${S.company.vendorCats.concat(['Crew','Expenses']).map(c=>`<option ${l.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div><label for="slf">Function</label><select id="slf"><option value="">Whole event</option>${fnNames(e).map(f=>`<option ${l.functionName===f?'selected':''}>${esc(f)}</option>`).join('')}</select></div></div><label for="sld">Description</label><input id="sld" value="${esc(l.desc)}" required><div class="grid g3" style="gap:8px"><div><label for="slq">Quantity</label><input id="slq" inputmode="decimal" value="${l.qty}"></div><div><label for="slu">Unit</label><select id="slu">${UNITS.map(u=>`<option ${l.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div><label for="slo">Owner</label>${userSel('slo',l.ownerId,u=>u.active!==false&&u.role!=='staff'&&u.role!=='accountant')}</div></div><div class="two"><div><label for="slk">Baseline unit cost (₹)</label><input id="slk" inputmode="decimal" value="${l.unitCostPaise/100}"></div><div><label for="slp">Unit price to client (₹)</label><input id="slp" inputmode="decimal" value="${l.unitPricePaise/100}"></div></div><div class="help">${isNew?'A new line after acceptance is scope you are buying that was not priced. If the client pays for it, raise a change order instead — it will create the line.':'Changing quantity or rate records a revision and shows in the margin bridge. The contract does not change — that needs a change order.'}</div>${ft('Save')}</form>`);F('f-sl').addEventListener('submit',x=>{x.preventDefault();const d={category:F('slc').value,functionName:F('slf').value,desc:F('sld').value.trim(),qty:parseFloat(F('slq').value)||0,unit:F('slu').value,ownerId:F('slo').value,unitCostPaise:toPaise(F('slk').value)||0,unitPricePaise:toPaise(F('slp').value)||0};if(!d.desc)return toast('Description required');if(isNew){const n=stamp(Object.assign({id:'sl_'+uid(),eventId:e.id,quoteLineId:null,baselineCostPaise:Math.round(d.qty*d.unitCostPaise),baselinePricePaise:Math.round(d.qty*d.unitPricePaise),etcPaise:null,etcBy:null,etcAt:null,etcNote:'',status:'open',releasedPaise:0,releaseReason:'',revisions:[]},d));S.scopeLines.push(n);audit('create','scopeLines',n.id,n.desc,e.id)}else{const changes=Object.keys(d).filter(k=>JSON.stringify(l[k])!==JSON.stringify(d[k]));changes.forEach(k=>l.revisions.push({ts:nowISO(),by:UI.userId,f:k,from:l[k],to:d[k]}));Object.assign(l,d);l.baselineCostPaise=Math.round(d.qty*d.unitCostPaise);l.baselinePricePaise=Math.round(d.qty*d.unitPricePaise);touch(l);audit('update','scopeLines',l.id,changes.join(','),e.id)}save();closeModal();render()})}
act('scope-link',({id,E})=>{const cm=S.commitments.find(x=>x.id===id);const e=ev(cm.eventId);const ls=scopeOf(e.id);const cur=allocOf(cm);openModal(`${hd('Link to scope lines: '+esc(vendor(cm.vendorId).name))}<form id="f-lk"><p class="small">Agreed ${inr(cm.agreedPaise+linkedChangeCost(cm.id))}. Tick the lines this agreement buys and split the amount. One vendor can cover several lines; several vendors can share one line.</p>${ls.map(l=>{const a=cur.find(x=>x.scopeLineId===l.id);return `<div class="row" style="gap:8px;margin:4px 0"><label class="chk" style="margin:0;flex:1"><input type="checkbox" class="lkc" value="${l.id}" ${a?'checked':''}> ${esc(l.category)} · ${esc(l.desc)} <span class="small muted">(baseline ${inr(l.baselineCostPaise)})</span></label><input class="lka" data-id="${l.id}" inputmode="decimal" value="${a?a.amountPaise/100:''}" placeholder="₹" style="width:110px"></div>`}).join('')}<div class="help">Amounts must add up to the agreed figure. Leave amounts blank to split equally.</div>${ft('Save')}</form>`);F('f-lk').addEventListener('submit',x=>{x.preventDefault();const ids=[...document.querySelectorAll('.lkc:checked')].map(c=>c.value);if(!ids.length){cm.allocation=[];cm.scopeLineIds=[];touch(cm);save();closeModal();render();return}const amts=ids.map(i=>{const v=document.querySelector(`.lka[data-id="${i}"]`).value;return v?toPaise(v):null});const total=cm.agreedPaise+linkedChangeCost(cm.id);let alloc;if(amts.every(a=>a==null)){const per=Math.floor(total/ids.length);alloc=ids.map((i,k)=>({scopeLineId:i,amountPaise:k===ids.length-1?total-per*(ids.length-1):per}))}else{if(amts.some(a=>a==null))return toast('Fill every amount or none');if(sum(amts)!==total)return toast(`Amounts add to ${inr(sum(amts))}, agreed is ${inr(total)}`);alloc=ids.map((i,k)=>({scopeLineId:i,amountPaise:amts[k]}))}cm.allocation=alloc;cm.scopeLineIds=ids;touch(cm);audit('update','commitments',cm.id,'linked to '+ids.length+' scope line(s)',e.id);save();closeModal();render()})});
/* ---------- Scenarios (what-if) ---------- */
function scenarioTotals(e,sc){const q=quoteTotals(e);const ls=scopeOf(e.id);const ratio=sc.guests&&e.guests?sc.guests/e.guests:1;let cost=0,price=0;ls.forEach(l=>{const o=(sc.lineOverrides||{})[l.id]||{};const qty=o.qty!=null?o.qty:(l.unit==='per guest'||l.unit==='per plate')?Math.round(l.qty*ratio):l.qty;const uc=o.unitCostPaise!=null?o.unitCostPaise:l.unitCostPaise;const up=o.unitPricePaise!=null?o.unitPricePaise:l.unitPricePaise;cost+=qty*uc;price+=qty*up});if(sc.markupPct!=null)price=Math.round(cost*(1+sc.markupPct/100));if(e.pricing==='costplus')price=cost+Math.round(cost*(sc.feePct!=null?sc.feePct:(e.feePct||0))/100);return {cost,price,margin:price-cost,gross:grossOf(e,price)}}
function scenariosCard(e){const scs=S.scenarios.filter(s=>s.eventId===e.id);if(!can('profit'))return '';const cur=(()=>{const ls=scopeOf(e.id);const cost=sum(ls,l=>l.qty*l.unitCostPaise),price=sum(ls,l=>l.qty*l.unitPricePaise);return {cost,price,margin:price-cost}})();return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>What-if scenarios (${scs.length})</h3><div class="small muted">Compare guest counts, supplier alternatives, markup or fee without touching the accepted contract. Nothing here changes a real figure until you raise a change order.</div></div>${locked(e)?'':`<button class="btn sm" data-act="scenario-new">+ Scenario</button>`}</div>${scs.length?`<div class="scroll" style="margin-top:6px"><table><thead><tr><th>Scenario</th><th class="r">Guests</th><th class="r">Cost</th><th class="r">Price</th><th class="r">Margin</th><th></th></tr></thead><tbody><tr><td><b>As contracted</b></td><td class="r num">${e.guests}</td><td class="r num">${inr(cur.cost)}</td><td class="r num">${inr(cur.price)}</td><td class="r num">${inr(cur.margin)} <span class="small muted">${pct(cur.margin,cur.price)}</span></td><td></td></tr>${scs.map(s=>{const t=scenarioTotals(e,s);return `<tr><td>${esc(s.name)}<div class="meta">${esc(s.note||'')} · ${esc(user(s.createdBy).name)}</div></td><td class="r num">${s.guests||e.guests}</td><td class="r num">${inr(t.cost)}</td><td class="r num">${inr(t.price)}</td><td class="r num" style="color:${t.margin<cur.margin?'var(--bad)':'var(--ok)'}">${inr(t.margin)} <span class="small muted">${pct(t.margin,t.price)}</span></td><td><button class="btn sm" data-act="scenario-del" data-id="${s.id}">Delete</button></td></tr>`}).join('')}</tbody></table></div>`:''}</div>`}
act('scenario-new',({E})=>{const e=E();const ls=scopeOf(e.id);openModal(`${hd('What-if scenario')}<form id="f-sn"><label for="snn">Name</label><input id="snn" required placeholder="450 guests, Spice Route instead of Royal"><div class="two"><div><label for="sng">Guests</label><input id="sng" inputmode="numeric" value="${e.guests}"></div><div><label for="snm">${e.pricing==='costplus'?'Fee %':'Markup % on cost (blank = keep line prices)'}</label><input id="snm" inputmode="decimal" value="${e.pricing==='costplus'?(e.feePct||0):''}"></div></div><label>Line overrides (leave blank to keep)</label><div class="scroll"><table><thead><tr><th>Line</th><th class="r">Qty</th><th class="r">Unit cost ₹</th><th class="r">Unit price ₹</th></tr></thead><tbody>${ls.map(l=>`<tr><td class="small">${esc(l.category)} · ${esc(l.desc)}<div class="meta">${l.qty} ${esc(l.unit)} · ${inr(l.unitCostPaise)} / ${inr(l.unitPricePaise)}</div></td><td><input class="sno" data-id="${l.id}" data-f="qty" style="width:70px;padding:5px" inputmode="decimal"></td><td><input class="sno" data-id="${l.id}" data-f="unitCostPaise" style="width:90px;padding:5px" inputmode="decimal"></td><td><input class="sno" data-id="${l.id}" data-f="unitPricePaise" style="width:90px;padding:5px" inputmode="decimal"></td></tr>`).join('')}</tbody></table></div><label for="snt">Note</label><input id="snt">${ft('Save scenario')}</form>`);F('f-sn').addEventListener('submit',x=>{x.preventDefault();const ov={};document.querySelectorAll('.sno').forEach(i=>{if(i.value===''){return}ov[i.dataset.id]=ov[i.dataset.id]||{};ov[i.dataset.id][i.dataset.f]=i.dataset.f==='qty'?parseFloat(i.value):toPaise(i.value)});const m=F('snm').value===''?null:parseFloat(F('snm').value);const s=stamp({id:uid(),eventId:e.id,name:F('snn').value.trim(),guests:parseInt(F('sng').value)||e.guests,lineOverrides:ov,markupPct:e.pricing==='costplus'?null:m,feePct:e.pricing==='costplus'?m:null,note:F('snt').value.trim()});S.scenarios.push(s);audit('create','scenarios',s.id,s.name,e.id);save();closeModal();render()})});
act('scenario-del',({id})=>{S.scenarios=S.scenarios.filter(s=>s.id!==id);save();render()});
/* ---------- Price book ---------- */
function priceBookFor(cat,e){const rows=S.priceBook.filter(p=>p.category===cat&&(!p.validUntil||p.validUntil>=todayStr()));if(!rows.length)return null;const byUnit={};rows.forEach(p=>{(byUnit[p.unit]=byUnit[p.unit]||[]).push(p)});const parts=Object.keys(byUnit).map(u=>{const rs=byUnit[u];const rates=rs.map(p=>p.ratePaise).sort((a,b)=>a-b);const med=rates[Math.floor(rates.length/2)];const n=sum(rs,p=>p.sampleSize||1);return `${inr(rates[0])}–${inr(rates[rates.length-1])} ${u} (median ${inr(med)}, n=${n}, ${[...new Set(rs.map(p=>p.location))].join('/')}, latest ${fmtShort(rs.map(p=>p.date).sort().slice(-1)[0])}, confidence ${rs.some(p=>p.confidence==='low')?'mixed':'ok'})`});return {text:parts.join('; ')}}
addPage('pricebook','Price book',vPriceBook,()=>can('quote'));
function vPriceBook(){const q=(S.ui.pbq||'').toLowerCase();const rows=S.priceBook.filter(p=>!q||(p.category+' '+p.desc+' '+p.location+' '+(vendor(p.vendorId).name||'')).toLowerCase().includes(q)).sort((a,b)=>a.category.localeCompare(b.category)||b.date.localeCompare(a.date));const stale=S.priceBook.filter(p=>p.validUntil&&p.validUntil<todayStr()).length;
  return `${topbar()}<div class="row between"><h1>Price book</h1><div class="row" style="gap:6px"><button class="btn sm" data-act="pb-harvest">Add from closed events</button><button class="btn sm pri" data-act="pb-add">+ Entry</button></div></div><div class="small muted" style="margin:4px 0 10px">Unit-aware benchmarks from your own agreements: rate per unit, where, when, how many data points, which vendor, valid until, and how much to trust it. Incomparable services are kept apart by unit and category. ${stale?stale+' expired entries are ignored in suggestions.':''}</div>
  <input id="pbq" data-act="pbq" value="${esc(S.ui.pbq||'')}" placeholder="Search category, description, place, vendor" style="max-width:360px;margin-bottom:10px">
  <div class="card"><div class="scroll"><table><thead><tr><th>Category · description</th><th class="r">Rate</th><th>Unit</th><th>Where · when</th><th class="r">n</th><th>Source</th><th>Confidence</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr class="${p.validUntil&&p.validUntil<todayStr()?'void':''}"><td><b>${esc(p.category)}</b> · ${esc(p.desc)}</td><td class="r num">${inr(p.ratePaise)}</td><td>${esc(p.unit)}</td><td>${esc(p.location)} · ${fmtShort(p.date)}${p.validUntil?' · valid to '+fmtShort(p.validUntil):''}</td><td class="r num">${p.sampleSize||1}</td><td class="small">${p.vendorId?esc(vendor(p.vendorId).name):esc(p.source||'manual')}${p.eventId&&ev(p.eventId)?' · '+esc(ev(p.eventId).name):''}</td><td><span class="pill ${p.confidence==='high'?'ok':p.confidence==='low'?'bad':'grey'}">${p.confidence||'medium'}</span></td><td><button class="btn sm" data-act="pb-del" data-id="${p.id}">Remove</button></td></tr>`).join('')||'<tr><td colspan="8" class="muted">Empty. Add entries or harvest closed events.</td></tr>'}</tbody></table></div></div>`}
ACTS_INPUT['pbq']=el=>{S.ui.pbq=el.value;saveUI();const pos=el.selectionStart;render();const n=F('pbq');if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}}};
act('pb-add',()=>{openModal(`${hd('Price book entry')}<form id="f-pb"><div class="two"><div><label for="pbc">Category</label><select id="pbc">${S.company.vendorCats.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div><label for="pbu">Unit</label><select id="pbu">${UNITS.map(u=>`<option>${u}</option>`).join('')}</select></div></div><label for="pbd">Description</label><input id="pbd" required placeholder="Sadhya, 400+ plates, Kochi"><div class="grid g3" style="gap:8px"><div><label for="pbr">Rate (₹ per unit)</label><input id="pbr" inputmode="decimal" required></div><div><label for="pbl">Location</label><input id="pbl" value="Kochi"></div><div><label for="pbdt">Date of rate</label><input id="pbdt" type="date" value="${todayStr()}"></div></div><div class="grid g3" style="gap:8px"><div><label for="pbv">Vendor (optional)</label><select id="pbv"><option value="">—</option>${S.vendors.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></div><div><label for="pbn">Sample size</label><input id="pbn" inputmode="numeric" value="1"></div><div><label for="pbcf">Confidence</label><select id="pbcf"><option>medium</option><option>high</option><option>low</option></select></div></div><label for="pbx">Valid until (optional)</label><input id="pbx" type="date">${ft('Add')}</form>`);F('f-pb').addEventListener('submit',x=>{x.preventDefault();const r=toPaise(F('pbr').value);if(!r)return toast('Rate required');S.priceBook.push(stamp({id:uid(),category:F('pbc').value,unit:F('pbu').value,desc:F('pbd').value.trim(),ratePaise:r,location:F('pbl').value.trim(),date:F('pbdt').value,vendorId:F('pbv').value||null,sampleSize:parseInt(F('pbn').value)||1,confidence:F('pbcf').value,validUntil:F('pbx').value||null,source:'manual'}));save();closeModal();render()})});
act('pb-del',({id})=>{S.priceBook=S.priceBook.filter(p=>p.id!==id);save();render()});
act('pb-harvest',()=>{let n=0;S.events.filter(e=>e.stage==='closed').forEach(e=>{costComms(e.id).forEach(cm=>{if(S.priceBook.some(p=>p.commitmentId===cm.id))return;const v=vendor(cm.vendorId);const unit=cm.perHead&&cm.pricedFor?'per guest':'lump sum';const rate=unit==='per guest'?Math.round(cm.agreedPaise/cm.pricedFor):cm.agreedPaise;S.priceBook.push(stamp({id:uid(),category:v.category,unit,desc:cm.scope||v.name,ratePaise:rate,location:(e.venue||'').split(',').slice(-1)[0].trim()||'Kochi',date:e.startDate,vendorId:cm.vendorId,eventId:e.id,commitmentId:cm.id,sampleSize:1,confidence:'high',validUntil:addDays(e.startDate,365),source:'closed event'}));n++})});save();render();toast(n?n+' entries added from closed events':'Nothing new to add')});
